-- T-SQL specific syntax: APPLY, MERGE, OUTPUT, FOR JSON/XML, hints, temp tables, variables
SELECT c.Id, c.Name, t.OrderId, t.Total FROM dbo.Customers c CROSS APPLY (SELECT TOP (3) o.OrderId, o.Total FROM dbo.Orders o WHERE o.CustomerId = c.Id ORDER BY o.Total DESC) AS t;
SELECT c.Id, c.Name, t.OrderId FROM dbo.Customers c OUTER APPLY (SELECT TOP (1) o.OrderId FROM dbo.Orders o WHERE o.CustomerId = c.Id ORDER BY o.OrderDate DESC) t;
SELECT o.OrderId, j.value FROM dbo.Orders o CROSS APPLY STRING_SPLIT(o.Tags, N',') AS j;
SELECT value FROM STRING_SPLIT(N'a,b,c', N',');
SELECT Id, Name FROM dbo.Customers FOR JSON PATH;
SELECT Id, Name FROM dbo.Customers FOR JSON PATH, ROOT('customers'), INCLUDE_NULL_VALUES;
SELECT c.Id, c.Name, (SELECT o.OrderId, o.Total FROM dbo.Orders o WHERE o.CustomerId = c.Id FOR JSON PATH) AS Orders FROM dbo.Customers c FOR JSON PATH, WITHOUT_ARRAY_WRAPPER;
SELECT Id, Name FROM dbo.Customers FOR JSON AUTO;
SELECT Id, Name FROM dbo.Customers FOR XML PATH('Customer'), ROOT('Customers');
SELECT STUFF((SELECT N',' + Name FROM dbo.Customers FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, N'');
SELECT Id, JSON_VALUE(Payload, '$.user.name') AS UserName, JSON_QUERY(Payload, '$.items') AS Items FROM dbo.Events WHERE ISJSON(Payload) = 1;
SELECT e.Id, j.* FROM dbo.Events e CROSS APPLY OPENJSON(e.Payload) WITH (Name NVARCHAR(100) '$.name', Qty INT '$.qty') AS j;
SELECT * FROM OPENJSON(@json) WITH (Id INT '$.id', Name NVARCHAR(50) '$.name');
SELECT * FROM dbo.Orders WITH (NOLOCK) WHERE Status = N'Open';
SELECT * FROM dbo.Orders o WITH (NOLOCK, INDEX(IX_Orders_Status)) JOIN dbo.Customers c WITH (NOLOCK) ON c.Id = o.CustomerId;
SELECT * FROM dbo.Orders WITH (UPDLOCK, ROWLOCK, READPAST) WHERE Status = 0;
SELECT * FROM dbo.Orders (NOLOCK);
SELECT o.Id FROM dbo.Orders o INNER HASH JOIN dbo.Customers c ON c.Id = o.CustomerId OPTION (MAXDOP 1, RECOMPILE);
SELECT * FROM dbo.Orders WHERE CustomerId = @CustomerId OPTION (OPTIMIZE FOR (@CustomerId = 42));
SELECT * FROM dbo.Orders OPTION (RECOMPILE);
SELECT @Total = SUM(Total) FROM dbo.Orders WHERE CustomerId = @CustomerId;
SELECT @a = 1, @b = 2;
SELECT TOP (@n) * FROM dbo.Orders ORDER BY Id;
SELECT * FROM dbo.Orders WHERE CreatedAt >= @From AND CreatedAt < @To AND (@Status IS NULL OR Status = @Status);
SELECT * FROM #recent r JOIN ##globaltemp g ON g.Id = r.Id;
SELECT GETDATE() AS Now, SYSDATETIMEOFFSET() AS NowOffset, NEWID() AS G, @@VERSION AS Ver, DB_NAME() AS Db, SUSER_SNAME() AS Usr;
SELECT CAST(N'abc' AS NVARCHAR(10)) + N'def' AS Concatenated, LEN(N'abc') AS L, DATALENGTH(N'abc') AS DL, CONCAT(N'a', N'b', N'c') AS C2, CONCAT_WS(N'-', N'a', N'b') AS C3;
SELECT TRIM(Name) AS T, LTRIM(RTRIM(Name)) AS LR, REPLACE(Name, N' ', N'_') AS R, SUBSTRING(Name, 1, 3) AS S, CHARINDEX(N'@', Email) AS At, LEFT(Name, 2) AS L2, RIGHT(Name, 2) AS R2, UPPER(Name) AS U FROM dbo.Customers;
SELECT 0x1F AS HexVal, 1.5E3 AS Sci, $5.00 AS Money;
SELECT [Order Details].[Unit Price], [Order Details].[Quantity] FROM [Order Details];
SELECT "Name" FROM "dbo"."Customers";
SELECT * FROM [MyServer].[MyDb].[dbo].[Customers];
SELECT * FROM MyDb.dbo.Customers;
SELECT * FROM MyDb..Customers;
SELECT a.Id FROM dbo.A a, dbo.B b WHERE a.Id = b.Id;
